{"path": "src/styles/global.css", "content": "/* Global styles */
*, *::before, *::after { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: 1.625;
  color: var(--color-text);
  background: var(--color-white);
  overflow-x: hidden;
}

img, svg, video { max-width: 100%; height: auto; }
img { display: block; background: var(--color-navy); }

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  color: var(--color-navy);
  margin: 0 0 var(--space-3);
  font-weight: 600;
  overflow-wrap: anywhere;
}
h1 { font-size: var(--text-h1); line-height: 1.22; letter-spacing: -0.01em; }
h2 { font-size: var(--text-h2); line-height: 1.25; letter-spacing: -0.01em; }
h3 { font-size: var(--text-h3); line-height: 1.4; }
p { margin: 0 0 var(--space-4); overflow-wrap: anywhere; }
ul, ol { margin: 0; padding: 0; }

a { color: var(--color-accent-strong); text-decoration: none; overflow-wrap: anywhere; }
a:hover { text-decoration: underline; }

button, input, select, textarea { font-family: inherit; font-size: var(--text-body); }
button { cursor: pointer; }

:focus-visible { outline: var(--focus-ring); outline-offset: 2px; }

.skip-link {
  position: absolute; left: -999px; top: 8px;
  background: var(--color-navy); color: var(--color-white);
  padding: var(--space-3) var(--space-4); border-radius: var(--radius-sm); z-index: 100;
}
.skip-link:focus { left: 8px; }

main:focus { outline: none; }

input:focus, select:focus, textarea:focus,
input:focus-visible, select:focus-visible, textarea:focus-visible,
button:focus-visible, a:focus-visible {
  outline: 3px solid var(--color-accent-strong); outline-offset: 2px;
}
.on-dark :focus-visible, .hero :focus-visible, .cta-band :focus-visible, .site-footer :focus-visible, .page-band :focus-visible,
.enterprise-panel :focus-visible, .engagement-card.premium :focus-visible {
  outline: 3px solid var(--color-accent-light); outline-offset: 2px;
}

.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; width: 100%; }

.section { padding-top: var(--space-8); padding-bottom: var(--space-8); }
.section-surface { background: var(--color-surface); }
.eyebrow {
  font-size: var(--text-eyebrow); line-height: 1.5; text-transform: uppercase;
  font-weight: 600; letter-spacing: .08em; color: var(--color-accent-strong); margin: 0 0 var(--space-3);
}
.lead { font-size: var(--text-lead); line-height: 1.65; }
.muted { color: var(--color-muted); }

/* Motion: CSS only, content is visible without JS */
@keyframes fade-up {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: none; }
}
.fade-in { animation: fade-up 600ms ease-out; }

/* Icons */
.line-icon { color: var(--color-accent); flex: none; }

/* Buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center; text-align: center;
  min-height: 48px; padding: 0 24px; border-radius: var(--radius-sm);
  font-family: var(--font-sans); font-weight: 600; font-size: 16px; line-height: 1.2;
  border: 1.5px solid transparent; cursor: pointer; text-decoration: none;
  transition: background-color 150ms ease, color 150ms ease;
}
.btn:hover { text-decoration: none; }
.btn-primary { background: var(--color-accent-strong); color: var(--color-white); }
.btn-primary:hover { background: var(--color-accent-strong-hover); color: var(--color-white); }
.btn-secondary { background: var(--color-white); color: var(--color-navy); border-color: var(--color-navy); }
.btn-secondary:hover { background: var(--color-surface); }
.btn-on-dark { background: var(--color-white); color: var(--color-navy); }
.btn-on-dark:hover { background: var(--color-surface); color: var(--color-navy); }
.btn-on-dark-secondary { background: transparent; color: var(--color-white); border-color: var(--color-white); }
.btn-on-dark-secondary:hover { background: rgba(255,255,255,.1); color: var(--color-white); }
.btn-header { min-height: 44px; }
.btn-block { width: 100%; }

/* Header */
.site-header {
  position: sticky; top: 0; z-index: 50; height: var(--header-h);
  background: var(--color-white); border-bottom: 1px solid transparent;
}
.site-header.is-scrolled { border-bottom-color: var(--color-border); }
.header-inner { display: flex; align-items: center; justify-content: space-between; height: 100%; gap: var(--space-4); }
.wordmark { display: inline-flex; align-items: center; gap: 8px; color: var(--color-navy); text-decoration: none; min-height: 44px; white-space: nowrap; }
.wordmark:hover { text-decoration: none; }
.wordmark-text { font-family: var(--font-serif); font-weight: 600; font-size: 20px; }
.wordmark-dark { color: var(--color-white); }
.wordmark-mark { flex: none; }

.nav-desktop { display: none; align-items: center; gap: var(--space-2); }
.nav-link {
  display: inline-flex; align-items: center; min-height: 44px; padding: 0 var(--space-3);
  color: var(--color-navy); font-weight: 500; border-bottom: 2px solid transparent; text-decoration: none;
}
.nav-link:hover { text-decoration: none; border-bottom-color: var(--color-border); }
.nav-link[aria-current="page"] { border-bottom-color: var(--color-accent); }
.nav-desktop .btn { margin-left: var(--space-3); }

.menu-toggle {
  display: inline-flex; align-items: center; gap: var(--space-2);
  background: none; border: none; color: var(--color-navy); font-weight: 600;
  min-height: 44px; min-width: 44px; padding: 0 var(--space-2);
}
.nav-mobile {
  position: absolute; top: 100%; left: 0; right: 0; background: var(--color-white);
  border-bottom: 1px solid var(--color-border); box-shadow: var(--shadow-card);
  padding: var(--space-3) 24px var(--space-5);
}
.nav-mobile ul { list-style: none; display: flex; flex-direction: column; gap: var(--space-1); }
.nav-mobile .nav-link { display: flex; min-height: 48px; width: 100%; }
.nav-mobile li:last-child { margin-top: var(--space-3); }

/* Hero */
.hero {
  position: relative; overflow: hidden; background: var(--color-navy); color: var(--color-white);
  min-height: 560px; display: flex; align-items: center; padding: var(--space-8) 0;
}
.hero-photo { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.hero-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(0deg, rgba(11,31,58,.88), rgba(11,31,58,.88));
}
.hero-motif { position: absolute; inset: 0; display: none; opacity: .35; pointer-events: none; }
.hero-motif .bell-curve-motif { width: 100%; height: 100%; }
.bell-curve-motif { display: block; }
.hero-grid { position: relative; z-index: 1; display: grid; gap: var(--space-6); align-items: center; }
.hero-copy { max-width: 720px; }
.hero h1 { color: var(--color-white); font-size: var(--text-display); line-height: 1.15; max-width: 14ch; }
.hero p.lead { color: var(--color-white); max-width: 560px; }
.hero-buttons { display: flex; flex-direction: column; gap: var(--space-3); margin-top: var(--space-5); }

/* Credibility strip */
.credibility-strip { position: relative; z-index: 2; background: var(--color-white); }
.cred-list { list-style: none; display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-4); padding: var(--space-5) 0; }
.cred-item { display: flex; flex-direction: column; align-items: flex-start; gap: var(--space-2); color: var(--color-navy); font-weight: 600; line-height: 1.4; }

/* Who we serve */
.serve-panels { display: grid; gap: var(--space-5); margin-top: var(--space-5); }
.panel { display: flex; flex-direction: column; border-radius: var(--radius-lg); overflow: hidden; box-shadow: var(--shadow-card); background: var(--color-white); border: 1px solid var(--color-border); }
.panel.card { padding: 0; }
.panel-photo { width: 100%; aspect-ratio: 16 / 9; object-fit: cover; }
.panel-body { padding: var(--space-5); display: flex; flex-direction: column; align-items: flex-start; flex: 1; }
.panel-body p { flex: 1; }
.smb-panel .panel-body { padding: var(--space-5); }
.enterprise-panel { background: var(--color-navy-deep); border-color: var(--color-accent); color: var(--color-white); }
.enterprise-panel h3 { color: var(--color-white); }
.enterprise-panel p { color: var(--color-muted-on-dark); }
.enterprise-panel a { color: var(--color-accent-light); }
.premium-label {
  display: inline-block; font-size: var(--text-eyebrow); font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
  color: var(--color-accent-light); border: 1px solid var(--color-accent); border-radius: var(--radius-pill);
  padding: 2px 12px; margin-bottom: var(--space-3);
}

/* Cards */
.card {
  background: var(--color-white); border: 1px solid var(--color-border); border-radius: var(--radius-md);
  padding: 24px; box-shadow: var(--shadow-card);
  transition: transform 200ms ease, box-shadow 200ms ease;
}
.card:hover { transform: translateY(-4px); box-shadow: var(--shadow-card-hover); }
.grid { display: grid; gap: var(--space-4); }
.pillars { display: grid; gap: var(--space-5); list-style: none; }
.pillar-card { display: flex; flex-direction: column; padding: 0; overflow: hidden; }
.pillar-photo { width: 100%; aspect-ratio: 16 / 7; object-fit: cover; }
.pillar-body { display: flex; flex-direction: column; flex: 1; padding: var(--space-5); }
.pillar-body p { flex: 1; }
.pillar-icon { color: var(--color-accent); margin-bottom: var(--space-3); }
.text-link { display: inline-flex; align-items: center; gap: 6px; min-height: 44px; font-weight: 600; }
.text-link svg { transition: transform 150ms ease; }
.text-link:hover svg { transform: translateX(4px); }

/* Pillar titles */
.pillar-title {
  font-family: var(--font-serif);
  font-size: var(--text-h3);
  font-weight: 600;
  color: var(--color-navy);
  margin: 0 0 var(--space-2);
}

/* Steps */
.how-we-work { position: relative; }
.steps { list-style: none; display: grid; gap: var(--space-6); margin-top: var(--space-6); }
.step-num {
  display: flex; align-items: center; justify-content: center; width: 48px; height: 48px; border-radius: 50%;
  background: var(--color-accent-strong); color: var(--color-white); font-family: var(--font-serif);
  font-weight: 600; font-size: 1.25rem; margin-bottom: var(--space-3); flex: none;
}

/* Case studies */
.case-grid { display: grid; gap: var(--space-5); margin-top: var(--space-5); }
.case-card { display: flex; flex-direction: column; }
.case-card h3 { margin-top: var(--space-2); }
.case-result { font-weight: 600; color: var(--color-navy); }
.placeholder-tag {
  display: inline-block; align-self: flex-start; background: var(--color-placeholder-bg); color: var(--color-placeholder-tag);
  font-size: var(--text-small); font-weight: 600; padding: 2px 10px; border-radius: var(--radius-pill); margin-bottom: var(--space-3);
}
.placeholder-note { font-style: italic; color: var(--color-muted); font-size: var(--text-small); margin: var(--space-3) 0 0; }

/* Testimonial */
.testimonial { background: var(--color-navy-deep); color: var(--color-white); padding: var(--space-8) 0; text-align: center; }
.testimonial-inner { max-width: 760px; }
.testimonial blockquote { margin: 0; }
.testimonial blockquote p { font-family: var(--font-serif); font-size: 1.5rem; line-height: 1.45; color: var(--color-white); }
.testimonial cite { display: block; font-style: normal; font-weight: 600; color: var(--color-accent-light); margin-top: var(--space-3); }
.testimonial-note { color: var(--color-muted-on-dark); font-style: italic; font-size: var(--text-small); margin: var(--space-4) 0 0; }

/* Why */
.why-layout { display: grid; gap: var(--space-6); }
.why-photo img { border-radius: var(--radius-lg); box-shadow: var(--shadow-card); margin-top: var(--space-4); aspect-ratio: 4 / 3; object-fit: cover; width: 100%; }
.why-list { display: grid; gap: var(--space-5); }
.why-point { display: flex; gap: var(--space-3); align-items: flex-start; }
.why-point svg { flex: none; color: var(--color-accent); margin-top: 2px; }
.why-point h3 { margin-bottom: var(--space-1); }
.why-point p { margin: 0; }

/* CTA band */
.cta-band { position: relative; overflow: hidden; background: var(--color-navy); color: var(--color-white); padding: var(--space-8) 0; text-align: center; }
.cta-band .container { position: relative; z-index: 1; }
.cta-motif { position: absolute; inset: 0; opacity: .3; pointer-events: none; }
.cta-motif .bell-curve-motif { width: 100%; height: 100%; }
.cta-band h2 { color: var(--color-white); }
.cta-band .btn { margin-top: var(--space-3); }

/* Interior page header */
.page-band { position: relative; overflow: hidden; background: var(--color-navy); color: var(--color-white); }
.page-band .data-grid-pattern { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; }
.page-band h1, .page-band h2 { color: var(--color-white); }
.page-band p, .page-band .lead { color: var(--color-white); }
.page-band a { color: var(--color-accent-light); }
.page-head { position: relative; padding-top: var(--space-8); padding-bottom: var(--space-7); }
.page-head p { max-width: 640px; }
.training-head { display: grid; gap: var(--space-5); align-items: center; }
.training-head p { max-width: 560px; }

.split { display: grid; gap: var(--space-6); align-items: center; }
.photo-frame { border-radius: var(--radius-lg); overflow: hidden; box-shadow: var(--shadow-card); background: var(--color-navy); }
.photo-frame img { width: 100%; aspect-ratio: 16 / 9; object-fit: cover; }
.why-heading { margin-top: var(--space-6); }

/* Services */
.service-section { padding: var(--space-8) 0; scroll-margin-top: 96px; border-top: 1px solid var(--color-border); }
.service-section:first-child { border-top: none; }
.service-header { display: grid; gap: var(--space-5); align-items: center; margin-bottom: var(--space-6); }
.service-items { display: grid; gap: var(--space-5); }
.service-item .line-icon { margin-bottom: var(--space-3); }
.service-item h3 { margin-bottom: var(--space-2); }
.service-item p { margin: 0; }
.engagement { display: flex; align-items: center; gap: var(--space-2); color: var(--color-accent-strong); font-weight: 600; margin: var(--space-5) 0 0; }
.engagement svg { flex: none; }

/* Engagements */
.engagement-grid { display: grid; gap: var(--space-5); }
.engagement-card { display: flex; flex-direction: column; padding: 0; overflow: hidden; }
.tier-body { display: flex; flex-direction: column; flex: 1; padding: var(--space-5); }
.tier-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: var(--space-3); }
.tier-top .premium-label { margin-bottom: 0; }
.tier-audience { color: var(--color-muted); font-weight: 600; margin-bottom: var(--space-2); }
.tier-timeline { display: flex; align-items: center; gap: var(--space-2); color: var(--color-accent-strong); font-weight: 600; }
.tier-timeline svg { flex: none; }
.check-list { list-style: none; flex: 1; display: flex; flex-direction: column; gap: var(--space-3); margin-bottom: var(--space-5); }
.check-list li { display: flex; gap: var(--space-3); align-items: flex-start; }
.check-list svg { flex: none; color: var(--color-accent); margin-top: 2px; }
.tier-body .btn { align-self: flex-start; }
.tier-photo { width: 100%; aspect-ratio: 16 / 9; object-fit: cover; }
.engagement-card.premium {
  background: var(--color-navy); border: 2px solid var(--color-accent); color: var(--color-white); scroll-margin-top: 96px;
}
.engagement-card.premium h2, .engagement-card.premium h3 { color: var(--color-white); }
.engagement-card.premium .tier-audience { color: var(--color-muted-on-dark); }
.engagement-card.premium .tier-timeline { color: var(--color-accent-light); }
.engagement-card.premium .check-list svg { color: var(--color-accent-light); }
.not-sure { margin: var(--space-6) 0 0; text-align: center; font-size: var(--text-lead); }

/* Training */
.filter-bar { display: flex; flex-wrap: wrap; gap: var(--space-2); margin-bottom: var(--space-4); }
.filter-bar button {
  min-height: 44px; padding: 0 var(--space-4); border-radius: var(--radius-sm);
  background: var(--color-white); color: var(--color-navy); border: 1.5px solid var(--color-input-border);
  font-weight: 600; transition: background-color 150ms ease, color 150ms ease;
}
.filter-bar button:hover { background: var(--color-surface); }
.filter-bar button.filter-selected, .filter-bar button[aria-pressed="true"] {
  background: var(--color-navy); color: var(--color-white); border-color: var(--color-navy);
}
.course-count { color: var(--color-muted); margin-bottom: var(--space-5); }
.course-grid { display: grid; gap: var(--space-5); }
.course-card { display: flex; flex-direction: column; height: 100%; }
.course-card .line-icon { margin-bottom: var(--space-3); }
.course-header { display: flex; flex-wrap: wrap; gap: var(--space-2); align-items: center; margin-bottom: var(--space-3); }
.audience-chip {
  background: var(--color-chip); color: var(--color-accent-strong); font-size: var(--text-small);
  font-weight: 600; padding: 2px 10px; border-radius: var(--radius-pill);
}
.format { color: var(--color-muted); font-size: var(--text-small); }
.course-card .duration { color: var(--color-muted); font-size: var(--text-small); }
.course-card hr { border: 0; border-top: 1px solid var(--color-border); margin: var(--space-4) 0; width: 100%; }
.learn-title { font-weight: 600; color: var(--color-navy); margin-bottom: var(--space-2); }
.course-card ul { padding-left: 20px; }
.course-card li { margin-bottom: var(--space-1); }
.empty-state { text-align: center; padding: var(--space-7) 0; }

/* About */
.about-grid { display: grid; gap: var(--space-5); margin-top: var(--space-5); }
.avatar-wrap { display: flex; align-items: center; gap: var(--space-3); margin-bottom: var(--space-4); }
.avatar-silhouette { width: 72px; height: 72px; flex: none; }
.avatar-caption { color: var(--color-muted); font-size: var(--text-small); }
.founder-role { color: var(--color-muted); font-weight: 600; }
.founder-card ul { padding-left: 20px; margin-bottom: var(--space-4); }
.value-card .line-icon { margin-bottom: var(--space-3); }

/* Contact */
.contact-grid { display: grid; gap: var(--space-6); padding-top: var(--space-7); padding-bottom: var(--space-8); }
.contact-form-card { max-width: 720px; width: 100%; }
.contact-side h2 { margin-top: var(--space-5); }
.next-steps { list-style: none; display: grid; gap: var(--space-4); }
.next-steps li { display: flex; align-items: center; gap: var(--space-3); }
.next-steps .step-num { margin-bottom: 0; }
.contact-page .field { margin-bottom: var(--space-5); display: flex; flex-direction: column; gap: var(--space-2); }
.contact-page label { font-weight: 600; color: var(--color-navy); display: flex; align-items: center; gap: var(--space-2); }
.field-head { display: flex; align-items: center; gap: var(--space-2); }
.form-note { font-size: var(--text-small); margin-bottom: var(--space-5); }
.required-tag {
  font-size: 0.75rem; font-weight: 600; color: var(--color-muted); border: 1px solid var(--color-input-border);
  border-radius: var(--radius-pill); padding: 0 8px; line-height: 1.5;
}
.form-control {
  border: 1.5px solid var(--color-input-border);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
  background: var(--color-white);
  color: var(--color-text);
  width: 100%;
  min-height: 48px;
}
.form-control:focus,
.form-control:focus-visible {
  border-color: var(--color-accent-strong);
  outline: 3px solid var(--color-accent-strong);
  outline-offset: 2px;
}
.form-control[aria-invalid="true"] {
  border-color: var(--color-error);
}
.contact-page textarea { min-height: 140px; resize: vertical; }
.contact-page input::placeholder { color: var(--color-muted); }
.contact-page .error-message {
  display: flex; align-items: flex-start; gap: 6px; color: var(--color-error); font-size: var(--text-small); margin: 0;
}
.contact-page .error-message svg { flex: none; margin-top: 2px; }
.success-banner {
  display: flex; align-items: center; gap: var(--space-3); background: var(--color-success-bg);
  color: var(--color-success); border-radius: var(--radius-sm); padding: var(--space-4); margin-bottom: var(--space-5);
  font-weight: 600;
}
.success-banner svg { flex: none; }
.contact-page button[type="submit"] { width: 100%; }

/* Not found */
.notfound-page { padding: var(--space-8) 0; }
.not-found-illustration { width: 160px; height: auto; margin-bottom: var(--space-4); }
.notfound-actions { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-4); margin-top: var(--space-5); }

/* Footer */
.site-footer { background: var(--color-navy); color: var(--color-white); padding: var(--space-8) 0 var(--space-6); }
.footer-inner { display: grid; gap: var(--space-6); }
.footer-brand p { color: var(--color-muted-on-dark); margin: var(--space-3) 0 0; }
.footer-brand a { color: var(--color-white); }
.footer-nav { display: grid; gap: var(--space-6); grid-template-columns: repeat(2, 1fr); align-content: start; }
.footer-col ul { list-style: none; }
.footer-col-title { font-family: var(--font-serif); font-weight: 600; font-size: 1.125rem; color: var(--color-white); margin: 0 0 var(--space-2); }
.footer-col-title a { color: var(--color-white); }
.footer-nav a { color: var(--color-white); display: inline-flex; align-items: center; min-height: 44px; }
.footer-nav a:hover { color: var(--color-accent-light); }
