/**
 * @jest-environment jsdom
 */
import * as React from 'react';
import { render, screen, cleanup } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import { Header } from '../../src/components/Header';

afterEach(cleanup);

describe('header navigation CTA button', () => {
  test('REPRO: header includes a distinct button labeled "Book a consultation"', () => {
    render(
      <MemoryRouter>
        <Header />
      </MemoryRouter>
    );

    // Find button by accessible name
    const ctaButton = screen.getByRole('button', { name: /book a consultation/i });
    expect(ctaButton).toBeInTheDocument();

    // Ensure it's a <button> element, not a link
    expect(ctaButton.tagName).toBe('BUTTON');
  });
});

